namespace ResearchAgent;

/// <summary>
/// In-memory notebook that the agent uses to store research findings.
/// </summary>
public sealed class Notebook
{
    private readonly List<NoteEntry> _entries = [];

    public void AddNote(string title, string content)
    {
        _entries.Add(new NoteEntry(title, content, DateTimeOffset.UtcNow));
    }

    public IReadOnlyList<NoteEntry> GetAllNotes() => _entries.AsReadOnly();

    public string GetSummaryOfNotes()
    {
        if (_entries.Count == 0)
            return "(no notes recorded yet)";

        return string.Join("\n\n", _entries.Select((e, i) =>
            $"[{i + 1}] {e.Title}\n{e.Content}"));
    }
}

public sealed record NoteEntry(string Title, string Content, DateTimeOffset Timestamp);

using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools exposed to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(Notebook notebook)
{
    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Use DuckDuckGo Instant Answer API (no key required) for real search results.
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            // Abstract text (main answer)
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"## {abstractSource}");
                results.AppendLine(abstractText);
                results.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 8) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        count++;
                    }
                }
            }

            var output = results.ToString().Trim();
            return string.IsNullOrWhiteSpace(output)
                ? $"No detailed results found for '{query}'. Try rephrasing the query."
                : output;
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed ({ex.StatusCode}): {ex.Message}. Try again with a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string TakeNote(
        [Description("Short descriptive title for the note")] string title,
        [Description("The content/findings to record")] string content)
    {
        notebook.AddNote(title, content);
        return $"Note saved: '{title}' ({notebook.GetAllNotes().Count} total notes)";
    }

    [Description("Read all notes taken so far. Use this to review what has been recorded before writing a summary.")]
    public string ReadNotes()
    {
        return notebook.GetSummaryOfNotes();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

namespace ResearchAgent;

public sealed class ResearchHostedService(
    IChatClient chatClient,
    ResearchTools tools,
    Notebook notebook,
    IHostApplicationLifetime lifetime) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════════╗");
        Console.WriteLine("║       🔍  AI Research Agent  🔍         ║");
        Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
        Console.WriteLine("╚══════════════════════════════════════════╝");
        Console.WriteLine();

        while (!stoppingToken.IsCancellationRequested)
        {
            Console.Write("Research topic> ");
            var topic = Console.ReadLine()?.Trim();

            if (string.IsNullOrEmpty(topic))
                continue;

            if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
                break;

            await RunResearchAsync(topic, stoppingToken);
            Console.WriteLine();
        }

        lifetime.StopApplication();
    }

    private async Task RunResearchAsync(string topic, CancellationToken ct)
    {
        Console.WriteLine($"\n📚 Researching: {topic}\n");

        var aiFunctions = AIFunctionFactory.Create(tools);

        var agent = new ChatClientAgent(chatClient,
            $"""
            You are a research agent. Your goal is to thoroughly research the given topic
            by searching the web multiple times with different queries, taking notes on
            key findings, and then producing a well-organized summary.

            Follow this process:
            1. Search the web with 2-3 different queries related to the topic
            2. Take notes on the most important findings from each search
            3. Read your notes to review everything collected
            4. Provide a final comprehensive summary to the user

            Always take notes before summarizing. Be thorough but concise.
            """,
            new ChatClientAgentOptions
            {
                Tools = [.. aiFunctions],
                MaximumIterations = 15,
                DefaultChatOptions = new ChatOptions
                {
                    Temperature = 0f,
                    MaxOutputTokens = 2048,
                },
            });

        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
        };

        try
        {
            await foreach (var message in agent.InvokeStreamingAsync(history, cancellationToken: ct))
            {
                if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
                {
                    Console.Write(message.Text);
                }
            }

            Console.WriteLine();
        }
        catch (OperationCanceledException)
        {
            Console.WriteLine("\n⚠️  Research cancelled.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"\n❌ Error during research: {ex.Message}");
        }

        // Show collected notes
        var notes = notebook.GetAllNotes();
        if (notes.Count > 0)
        {
            Console.WriteLine($"\n📝 Notes collected: {notes.Count}");
            foreach (var note in notes)
            {
                Console.WriteLine($"   • {note.Title}");
            }
        }
    }
}

