using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools exposed to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(Notebook notebook)
{
    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Use DuckDuckGo Instant Answer API (no key required) for real search results.
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            // Abstract text (main answer)
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.AppendLine($"## {abstractSource}");
                results.AppendLine(abstractText);
                results.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 8) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.AppendLine($"- {text}");
                        count++;
                    }
                }
            }

            var output = results.ToString().Trim();
            return string.IsNullOrWhiteSpace(output)
                ? $"No detailed results found for '{query}'. Try rephrasing the query."
                : output;
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed ({ex.StatusCode}): {ex.Message}. Try again with a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string TakeNote(
        [Description("Short descriptive title for the note")] string title,
        [Description("The content/findings to record")] string content)
    {
        notebook.AddNote(title, content);
        return $"Note saved: '{title}' ({notebook.GetAllNotes().Count} total notes)";
    }

    [Description("Read all notes taken so far. Use this to review what has been recorded before writing a summary.")]
    public string ReadNotes()
    {
        return notebook.GetSummaryOfNotes();
    }
}

