namespace ResearchAgent;

/// <summary>
/// In-memory notebook that the agent uses to store research findings.
/// </summary>
public sealed class Notebook
{
    private readonly List<NoteEntry> _entries = [];

    public void AddNote(string title, string content)
    {
        _entries.Add(new NoteEntry(title, content, DateTimeOffset.UtcNow));
    }

    public IReadOnlyList<NoteEntry> GetAllNotes() => _entries.AsReadOnly();

    public string GetSummaryOfNotes()
    {
        if (_entries.Count == 0)
            return "(no notes recorded yet)";

        return string.Join("\n\n", _entries.Select((e, i) =>
            $"[{i + 1}] {e.Title}\n{e.Content}"));
    }
}

public sealed record NoteEntry(string Title, string Content, DateTimeOffset Timestamp);

