 using System.Reflection;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.Hosting;
 using Microsoft.Agents.AI;

 namespace ResearchAgent;

 public sealed class ResearchHostedService(
     IChatClient chatClient,
     ResearchTools tools,
     Notebook notebook,
     IHostApplicationLifetime lifetime) : BackgroundService
 {
     protected override async Task ExecuteAsync(CancellationToken stoppingToken)
     {
         Console.WriteLine("╔══════════════════════════════════════════╗");
         Console.WriteLine("║       🔍  AI Research Agent  🔍         ║");
         Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
         Console.WriteLine("╚══════════════════════════════════════════╝");
         Console.WriteLine();

         while (!stoppingToken.IsCancellationRequested)
         {
             Console.Write("Research topic> ");
             var topic = Console.ReadLine()?.Trim();

             if (string.IsNullOrEmpty(topic))
                 continue;

             if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
                 break;

             await RunResearchAsync(topic, stoppingToken);
             Console.WriteLine();
         }

         lifetime.StopApplication();
     }

     private async Task RunResearchAsync(string topic, CancellationToken ct)
     {
         Console.WriteLine($"\n📚 Researching: {topic}\n");

         var toolMethods = typeof(ResearchTools)
             .GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);

         var aiFunctions = toolMethods
             .Select(m => AIFunctionFactory.Create(m, tools))
             .ToList<AITool>();

         var agent = new ChatClientAgent(chatClient,
             instructions: """
                 You are a research agent. Your goal is to thoroughly research the given topic
                 by searching the web multiple times with different queries, taking notes on
                 key findings, and then producing a well-organized summary.

                 Follow this process:
                 1. Search the web with 2-3 different queries related to the topic
                 2. Take notes on the most important findings from each search
                 3. Read your notes to review everything collected
                 4. Provide a final comprehensive summary to the user

                 Always take notes before summarizing. Be thorough but concise.
                 """,
             name: "ResearchAgent",
             description: "An agent that researches topics using web search and note-taking.",
             tools: aiFunctions);

         var runOptions = new ChatClientAgentRunOptions
         {
             ChatOptions = new ChatOptions
             {
                 Temperature = 0f,
                 MaxOutputTokens = 2048,
             },
         };

         var session = await agent.CreateSessionAsync(cancellationToken: ct);

         try
         {
             await foreach (var update in agent.RunStreamingAsync(
                 $"Research the following topic and provide a summary: {topic}",
                 session,
                 runOptions,
                 ct))
             {
                 if (update.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(update.Text))
                 {
                     Console.Write(update.Text);
                 }
             }

             Console.WriteLine();
         }
         catch (OperationCanceledException)
         {
             Console.WriteLine("\n⚠️  Research cancelled.");
         }
         catch (Exception ex)
         {
             Console.WriteLine($"\n❌ Error during research: {ex.Message}");
         }

         var notes = notebook.GetAllNotes();
         if (notes.Count > 0)
         {
             Console.WriteLine($"\n📝 Notes collected: {notes.Count}");
             foreach (var note in notes)
             {
                 Console.WriteLine($"   • {note.Title}");
             }
         }
     }
 }

