2. using System.Net;
3. using System.Text;
4. using System.Text.Json;
5. using Microsoft.Extensions.AI;
6. 
7. namespace ResearchAgent;
8. 
9. /// <summary>
10. /// Tools exposed to the research agent for web searching and note-taking.
11. /// </summary>
12. public sealed class ResearchTools(Notebook notebook)
13. {
14.     [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
15.     public async Task<string> SearchWeb(
16.         [Description("The search query string")] string query)
17.     {
18.         // Use DuckDuckGo Instant Answer API (no key required) for real search results.
19.         using var http = new HttpClient();
20.         http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
21. 
22.         var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1&skip_disambig=1";
23. 
24.         try
25.         {
26.             var json = await http.GetStringAsync(url);
27.             using var doc = JsonDocument.Parse(json);
28.             var root = doc.RootElement;
29. 
30.             var results = new StringBuilder();
31. 
